class Solution:
    def firstUniqChar(self, s: str) -> int:
        cnt = {}                                # 字符 -> 出现次数
        for ch in s:
            cnt[ch] = cnt.get(ch, 0) + 1        # 没见过的当作 0
        for i, ch in enumerate(s):              # 再按原来的顺序找
            if cnt[ch] == 1:
                return i
        return -1

