class Solution {
    public int firstUniqChar(String s) {
        Map<Character, Integer> cnt = new HashMap<>();      // 字符 -> 出现次数
        for (char ch : s.toCharArray()) {
            cnt.put(ch, cnt.getOrDefault(ch, 0) + 1);       // 没见过的当作 0
        }
        for (int i = 0; i < s.length(); i++) {              // 再按原来的顺序找
            if (cnt.get(s.charAt(i)) == 1) {
                return i;
            }
        }
        return -1;
    }
}

