class Solution:
    def intersection(self, nums1: List[int], nums2: List[int]) -> List[int]:
        seen = set(nums1)                       # 查一个数在不在：O(1)
        res = set()                             # 答案也用集合，自动去重
        for x in nums2:
            if x in seen:
                res.add(x)
        return list(res)

