class Solution {
    public int[] intersection(int[] nums1, int[] nums2) {
        Set<Integer> seen = new HashSet<>();        // 查一个数在不在：O(1)
        for (int x : nums1) {
            seen.add(x);
        }
        Set<Integer> res = new HashSet<>();         // 答案也用集合，自动去重
        for (int x : nums2) {
            if (seen.contains(x)) {
                res.add(x);
            }
        }
        int[] ans = new int[res.size()];
        int k = 0;
        for (int x : res) {
            ans[k++] = x;
        }
        return ans;
    }
}

